const body = $('Webhook').first().json.body;

const email = body.email?.toLowerCase().trim();
const token = body.token;

if (!email) {
  throw new Error('Email is required');
}

if (!token) {
  throw new Error('Invite token is required');
}

// Проверка домена
const allowedDomain = '@sedamedical.com';
if (!email.endsWith(allowedDomain)) {
  throw new Error('Only ' + allowedDomain + ' emails are allowed');
}

// Генерация 6-значного кода
const code = String(Math.floor(100000 + Math.random() * 900000));

// Экранируем email для SQL
const safeEmail = email.replace(/'/g, "''");

return {
  json: {
    email: email,
    safe_email: safeEmail,
    token: token,
    code: code
  }
};

const tokenResult = $input.first().json;
const inputData = $('Generate Code').first().json;

if (!tokenResult || !tokenResult.id) {
  throw new Error('Ссылка для регистрации недействительна или истекла');
}

return { json: inputData };

const results = $input.all();
const inputData = $('Check Token Result').first().json;

// Проверяем, есть ли результаты и есть ли id
let userResult = null;
if (results && results.length > 0) {
  const firstResult = results[0].json;
  // Проверяем, что это не пустой объект
  if (firstResult && typeof firstResult.id !== 'undefined' && firstResult.id !== null) {
    userResult = firstResult;
  }
}

// Для отладки выводим информацию
console.log('Results count:', results.length);
console.log('User result:', JSON.stringify(userResult));

// 1. Пользователь не найден в базе - возвращаем структурированный ответ
if (!userResult) {
  return {
    json: {
      success: false,
      error_code: 'email_not_found',
      message: 'Email не найден в системе. Проверьте правильность написания или обратитесь в HR.',
      data: {
        email: inputData.email
      }
    }
  };
}

// 2. Проверяем статус пароля
const passwordStatus = userResult.password_status;
console.log('Password status:', passwordStatus);

// Если пароль уже установлен - аккаунт зарегистрирован
// Возвращаем структурированный ответ вместо ошибки
if (passwordStatus === 'has_password') {
  return {
    json: {
      success: false,
      error_code: 'already_registered',
      message: 'Этот аккаунт уже зарегистрирован. Пожалуйста, войдите или сбросьте пароль.',
      data: {
        email: inputData.email,
        full_name: userResult.full_name
      }
    }
  };
}

const lastCodeAtMs = Number(userResult.last_code_at_ms);
if (Number.isFinite(lastCodeAtMs) && lastCodeAtMs > 0) {
  const elapsed = Date.now() - lastCodeAtMs;
  if (elapsed < 60 * 1000) {
    const retryAfter = Math.max(1, Math.ceil((60 * 1000 - Math.max(0, elapsed)) / 1000));
    return {
      json: {
        success: false,
        error_code: 'resend_cooldown',
        retry_after_seconds: retryAfter,
        message: 'Код уже отправлен. Подождите ' + retryAfter + ' сек. перед повторной отправкой.',
        data: { email: inputData.email }
      }
    };
  }
}

// 3. Пользователь найден и пароль не установлен - можно регистрировать
return {
  json: {
    success: true,
    ...inputData,
    user_id: userResult.id,
    full_name: userResult.full_name,
    db_email: userResult.email,
    password_status: passwordStatus
  }
};

const codeResult = $('Save Code').first().json;
const inputData = $('Verify User').first().json;

// Email отправлен через предыдущую ноду
// Возвращаем успешный ответ без кода

return {
  json: {
    success: true,
    message: 'Код подтверждения отправлен на ' + inputData.email,
    data: {
      email: inputData.email,
      full_name: inputData.full_name,
      expires_at: codeResult.expires_at
    }
  }
};

// Ошибка регистрации (уже зарегистрирован или email не найден) - просто передаём ответ дальше
const inputData = $('Verify User').first().json;

return {
  json: inputData
};
